// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, random, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadGreatVibes = makeLoadFont('GreatVibes');
const loadInter = makeLoadFont('Inter');
import { noise2D } from "@remotion/noise";

// Library: noise — Organic fly trajectories and light flicker patterns
const { fontFamily: titleFontFamily } = loadGreatVibes();
const { fontFamily: subtitleFontFamily } = loadInter();



export type FirefliesMeadowProps = Record<string, any>;

const FirefliesMeadow: React.FC<FirefliesMeadowProps> = ({
  backgroundColor = "#040814",
  transparentBackground = false,
  durationInSeconds = 15,
  fireflyCount = 65,
  meadowTitle = "Midsummer Night's Dream",
  meadowSubtitle = "A canvas illuminated by nature's softest sparks",
  glowColor = "#e1ff6b",
  accentGlowColor = "#ffb03a",
  windSpeed = 0.6,
  maxBaseSize = 4.5,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Generate completely deterministic layout & individual parameter seeds once
  const fireflies = useMemo(() => {
    return Array.from({ length: fireflyCount }).map((_, i) => {
      const seedX = `firefly-x-${i}`;
      const seedY = `firefly-y-${i}`;
      const seedSpeed = `firefly-speed-${i}`;
      const seedOffset = `firefly-offset-${i}`;
      const seedColor = `firefly-color-${i}`;

      // Distribute widely on/off canvas edges so some continuously enter and exit
      const startX = random(seedX) * (width * 1.4) - width * 0.2;
      const startY = random(seedY) * (height * 1.3) - height * 0.2;
      const speedFactor = 0.5 + random(seedSpeed) * 1.5;
      const noiseOffset = random(seedOffset) * 10000;
      const size = 1.5 + random(seedSpeed) * maxBaseSize;
      const isAccent = random(seedColor) > 0.75; // 25% get warm accent amber tone

      return {
        startX,
        startY,
        speedFactor,
        noiseOffset,
        size,
        color: isAccent ? accentGlowColor : glowColor,
      };
    });
  }, [fireflyCount, width, height, maxBaseSize, glowColor, accentGlowColor]);

  // Meadow Blades of Grass (layered background/foreground shapes to create depth)
  const blades = useMemo(() => {
    return Array.from({ length: 45 }).map((_, i) => {
      const seedX = `blade-x-${i}`;
      const seedHeight = `blade-h-${i}`;
      const seedCurve = `blade-c-${i}`;
      const xPos = random(seedX) * width;
      const bHeight = 150 * s + random(seedHeight) * 200 * s;
      const curve = (random(seedCurve) - 0.5) * 60 * s;
      const depth = random(seedX) > 0.5 ? "back" : "front"; // divide into layers

      return { xPos, bHeight, curve, depth };
    }, [width, s]);
  }, [width, s]);

  // Master Intro Animation Sequence
  const overlayOpacity = interpolate(frame, [0, 60], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const textEntranceProgress = interpolate(frame, [30, 90], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const textYOffset = (1 - textEntranceProgress) * 40 * s;
  const textOpacity = textEntranceProgress;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Background Gradient */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: "radial-gradient(circle at 50% 80%, #0c1833 0%, #03070f 100%)",
          mixBlendMode: "normal",
        }}
      />

      {/* Deep Background Silhouette Grass */}
      <svg
        style={{
          position: "absolute",
          bottom: 0,
          left: 0,
          width: "100%",
          height: 400 * s,
          pointerEvents: "none",
          zIndex: 2,
          opacity: 0.8,
        }}
      >
        {blades
          .filter((b) => b.depth === "back")
          .map((b, idx) => {
            const currentWind = Math.sin(frame * 0.02 * windSpeed + idx) * 15 * s;
            const d = `M ${b.xPos} 400 C ${b.xPos + b.curve * 0.3} ${400 - b.bHeight * 0.5}, ${b.xPos + b.curve + currentWind} ${400 - b.bHeight}, ${b.xPos + b.curve + 5 * s + currentWind} ${400 - b.bHeight} C ${b.xPos + b.curve + currentWind} ${400 - b.bHeight * 0.9}, ${b.xPos + 5 * s} 400, ${b.xPos + 5 * s} 400 Z`;
            return <path key={`back-grass-${idx}`} d={d} fill="#050a14" />;
          })}
      </svg>

      {/* Floating Fireflies Layer */}
      <div style={{ position: "absolute", inset: 0, zIndex: 3 }}>
        {fireflies.map((firefly, idx) => {
          const t = frame / fps;

          // Compute deterministic path drift via layered Simplex Noise
          const xDrift = noise2D("x-drift", t * 0.15 * windSpeed, firefly.noiseOffset) * 200 * s;
          const yDrift = noise2D("y-drift", t * 0.12 * windSpeed, firefly.noiseOffset + 500) * 150 * s;

          // Continuous gentle bias/drift representing gentle meadow wind currents
          const windBiasX = t * 18 * windSpeed * firefly.speedFactor * s;
          const windBiasY = Math.sin(t * 0.3 + idx) * 35 * s;

          // Sum coordinates
          let posX = firefly.startX + xDrift + windBiasX;
          let posY = firefly.startY + yDrift + windBiasY;

          // Seamless Wrap-around Boundary logic to ensure infinite dynamic movement inside canvas
          posX = ((posX + width * 0.2) % (width * 1.4)) - width * 0.2;
          if (posX < -width * 0.2) posX += width * 1.4;

          posY = ((posY + height * 0.2) % (height * 1.4)) - height * 0.2;
          if (posY < -height * 0.2) posY += height * 1.4;

          // Soft organic breathing glow frequency pattern (flicker factor)
          const rawFlicker = noise2D("flicker", t * 1.4 * firefly.speedFactor, firefly.noiseOffset * 2);
          const baseBrightness = interpolate(rawFlicker, [-1, 1], [0.15, 1.0]);

          // Global Entrance fade-in for smooth composition initialization
          const introFade = interpolate(frame, [0, 45 + idx * 0.3], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          const currentOpacity = baseBrightness * introFade;

          return (
            <div
              key={`firefly-${idx}`}
              style={{
                position: "absolute",
                left: posX,
                top: posY,
                width: firefly.size * s,
                height: firefly.size * s,
                borderRadius: "50%",
                backgroundColor: firefly.color,
                opacity: currentOpacity,
                boxShadow: `
                  0 0 ${firefly.size * 3 * s}px ${firefly.color}, 
                  0 0 ${firefly.size * 6 * s}px ${firefly.color}, 
                  0 0 ${firefly.size * 12 * s}px ${firefly.color}
                `,
                transform: `scale(${interpolate(rawFlicker, [-1, 1], [0.9, 1.15])})`,
                transition: "none",
                willChange: "transform, opacity, left, top",
              }}
            />
          );
        })}
      </div>

      {/* Foreground Silhouette Grass */}
      <svg
        style={{
          position: "absolute",
          bottom: 0,
          left: 0,
          width: "100%",
          height: 400 * s,
          pointerEvents: "none",
          zIndex: 4,
        }}
      >
        {blades
          .filter((b) => b.depth === "front")
          .map((b, idx) => {
            const currentWind = Math.sin(frame * 0.02 * windSpeed + idx + 10) * 22 * s;
            const d = `M ${b.xPos} 400 C ${b.xPos + b.curve * 0.35} ${400 - b.bHeight * 0.5}, ${b.xPos + b.curve + currentWind} ${400 - b.bHeight}, ${b.xPos + b.curve + 6 * s + currentWind} ${400 - b.bHeight} C ${b.xPos + b.curve + currentWind} ${400 - b.bHeight * 0.95}, ${b.xPos + 6 * s} 400, ${b.xPos + 6 * s} 400 Z`;
            return <path key={`front-grass-${idx}`} d={d} fill="#02040a" />;
          })}
      </svg>

      {/* Typography Overlay Content */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          zIndex: 5,
          pointerEvents: "none",
          padding: `0 ${width * 0.05}px`,
        }}
      >
        <h1
          style={{
            fontFamily: titleFontFamily,
            fontSize: 90 * s,
            color: "#fcfef2",
            margin: 0,
            textShadow: `0 2px 20px rgba(225,255,107,0.25)`,
            opacity: textOpacity,
            transform: `translateY(${textYOffset}px)`,
            textAlign: "center",
            letterSpacing: "1.5px",
            fontWeight: 400,
            transition: "none",
          }}
        >
          {meadowTitle}
        </h1>
        <p
          style={{
            fontFamily: subtitleFontFamily,
            fontSize: 22 * s,
            color: "#a4b3c6",
            marginTop: 20 * s,
            marginBottom: 0,
            letterSpacing: "4px",
            textTransform: "uppercase",
            opacity: textOpacity * 0.85,
            transform: `translateY(${textYOffset * 0.7}px)`,
            textAlign: "center",
            maxWidth: "60%",
            lineHeight: 1.6,
            fontWeight: 300,
            transition: "none",
          }}
        >
          {meadowSubtitle}
        </p>
      </div>

      {/* Cinematic Ambient Overlay & Soft Vignette */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: "radial-gradient(circle, transparent 35%, rgba(1, 3, 8, 0.85) 100%)",
          pointerEvents: "none",
          zIndex: 6,
        }}
      />

      {/* Fade In on Start Overlay */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          backgroundColor: "#010308",
          opacity: overlayOpacity,
          pointerEvents: "none",
          zIndex: 10,
        }}
      />
    </AbsoluteFill>
  );
};

export default FirefliesMeadow;